    Clear-Host
    Write-Host "======================================================================" -ForegroundColor Cyan
    Write-Host "  YapAnel Hi-Fi & Party Mode v0.2.8 — Автоматический установщик для Станции Макс" -ForegroundColor Yellow
    Write-Host "======================================================================" -ForegroundColor Cyan
    Write-Host ""
}

function Show-ErrorAndExit([string]$msg) {
    Write-Host ""
    Write-Host "----------------------------------------------------------------------" -ForegroundColor Red
    Write-Host " [ОШИБКА] $msg" -ForegroundColor Red
    Write-Host "----------------------------------------------------------------------" -ForegroundColor Red
    Write-Host ""
    Write-Host "Нажмите Enter для выхода..." -ForegroundColor Gray
    Read-Host
    exit 1
}

Write-Header

# 1. Поиск или скачивание ADB
Write-Host "[1/6] Проверка инструмента ADB (Android Debug Bridge)..." -ForegroundColor Green
$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not $ScriptDir) { $ScriptDir = Get-Location }

$AdbExe = $null
$possibleAdb = @(
    "$ScriptDir\adb.exe",
    "$ScriptDir\platform-tools\adb.exe",
    "$ScriptDir\tools\platform-tools\adb.exe",
    (Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe"),
    "adb"
)

foreach ($cand in $possibleAdb) {
    try {
        $res = & $cand version 2>$null
        if ($LASTEXITCODE -eq 0) {
            $AdbExe = $cand
            break
        }
    } catch {}
}

if (-not $AdbExe) {
    Write-Host "      ADB не найден в системе. Загружаю официальный Google platform-tools..." -ForegroundColor Yellow
    $toolsDir = Join-Path $ScriptDir "tools"
    $zipPath = Join-Path $toolsDir "platform-tools.zip"
    try {
        New-Item -ItemType Directory -Force -Path $toolsDir | Out-Null
        $url = "https://dl.google.com/android/repository/platform-tools-latest-windows.zip"
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $wc = New-Object System.Net.WebClient
        $wc.DownloadFile($url, $zipPath)
        Expand-Archive -LiteralPath $zipPath -DestinationPath $toolsDir -Force
        Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
        $AdbExe = Join-Path $toolsDir "platform-tools\adb.exe"
        if (-not (Test-Path $AdbExe)) {
            Show-ErrorAndExit "Не удалось распаковать adb.exe из архива platform-tools."
        }
        Write-Host "      ADB успешно загружен и настроен." -ForegroundColor Green
    } catch {
        Show-ErrorAndExit "Не удалось автоматически скачать ADB. Проверьте подключение к интернету или поместите adb.exe рядом со скриптом."
    }
} else {
    Write-Host "      Найден ADB: $AdbExe" -ForegroundColor Gray
}

# 2. Определение IP-адреса колонки
Write-Host ""
Write-Host "[2/6] Подключение к Станции Макс по сети (Wi-Fi)..." -ForegroundColor Green
$ipFile = Join-Path $ScriptDir ".station_ip"
if (-not $TargetIP -and (Test-Path $ipFile)) {
    $savedIp = (Get-Content $ipFile -Raw -Encoding UTF8).Trim()
    if ($savedIp) {
        Write-Host "      Запомненный адрес: $savedIp (нажмите Enter для использования или введите новый)" -ForegroundColor Gray
        $promptIp = Read-Host "      IP колонки [$savedIp]"
        if (-not $promptIp) { $TargetIP = $savedIp } else { $TargetIP = $promptIp.Trim() }
    }
}

while (-not $TargetIP) {
    $promptIp = Read-Host "      Введите IP-адрес Яндекс Станции Макс (например 192.168.1.100)"
    $TargetIP = $promptIp.Trim()
}

$TargetIP = $TargetIP -replace ":5555$",""
Set-Content -LiteralPath $ipFile -Value $TargetIP -Encoding UTF8 -Force

$Device = "${TargetIP}:5555"
Write-Host "      Подключение к $Device..." -ForegroundColor Cyan

# Подключение ADB
& $AdbExe disconnect $Device 2>$null | Out-Null
$connOut = (& $AdbExe connect $Device 2>&1) | Out-String
if ($connOut -match "failed|unable|cannot|refused") {
    Start-Sleep -Seconds 1
    $connOut = (& $AdbExe connect $Device 2>&1) | Out-String
}

$devList = (& $AdbExe devices) | Out-String
if ($devList -notmatch [regex]::Escape($Device)) {
    Show-ErrorAndExit ("Не удалось подключиться к колонке по адресу " + $Device + ".`nУбедитесь, что:`n1. Колонка включена и в одной сети Wi-Fi с компьютером.`n2. На Станции включен ADB по сети (порт 5555).`n3. IP-адрес " + $TargetIP + " указан верно.")
}

Write-Host "      Успешно подключено к $Device!" -ForegroundColor Green

# 3. Проверка прав Root (su)
Write-Host ""
Write-Host "[3/6] Проверка Root-доступа (su)..." -ForegroundColor Green
$suId = (& $AdbExe -s $Device shell "su -c id" 2>&1) | Out-String
if ($suId -notmatch "uid=0\(root\)") {
    Show-ErrorAndExit "На колонке нет Root-прав (команда su не вернула uid=0).`nДля управления аппаратным DSP усилителей Silergy и работы панели необходим Root-доступ к Станции Макс."
}
Write-Host "      Root-доступ подтверждён (uid=0 root)." -ForegroundColor Green

# 4. Проверка и установка зависимостей Python
Write-Host ""
Write-Host "[4/6] Проверка Python и установка зависимостей на колонке..." -ForegroundColor Green
$pyCheck = (& $AdbExe -s $Device shell 'su -c "test -f /data/python/bin/python3 && echo OK || echo MISSING"' 2>&1) | Out-String
if ($pyCheck -notmatch "OK") {
    Show-ErrorAndExit "На колонке отсутствует Python 3 в /data/python.`nУстановите автономный пакет python311_aarch64 на колонку."
}

Write-Host "      Установка/проверка библиотек tinytuya, requests, cryptography..." -ForegroundColor Cyan
$pipCmd = 'su -c "/data/python/bin/python3 -m pip install tinytuya requests cryptography --no-warn-script-location"'
$pipOut = (& $AdbExe -s $Device shell $pipCmd 2>&1) | Out-String

$depCmd = 'su -c "/data/python/bin/python3 -c "import tinytuya, requests, cryptography; print(\"DEPS_OK\")""'
$depCheck = (& $AdbExe -s $Device shell $depCmd 2>&1) | Out-String
if ($depCheck -notmatch "DEPS_OK") {
    Show-ErrorAndExit ("Ошибка проверки Python-зависимостей на колонке:`n" + $depCheck)
}
Write-Host "      Все зависимости (tinytuya, requests, cryptography) готовы!" -ForegroundColor Green

# 5. Распаковка и заливка YapAnel
Write-Host ""
Write-Host "[5/6] Заливка файлов панели YapAnel на Станцию..." -ForegroundColor Green
$localTar = Join-Path $ScriptDir "yapanel_max.tar.gz"
$tempTarCreated = $false

if (-not (Test-Path $localTar)) {
    Write-Host "      Извлечение встроенного архива файлов панели..." -ForegroundColor Gray
    $localTar = [System.IO.Path]::GetTempFileName() + ".tar.gz"
    $bytes = [System.Convert]::FromBase64String($EmbeddedTarB64)
    [System.IO.File]::WriteAllBytes($localTar, $bytes)
    $tempTarCreated = $true
}

$remoteTmp = "/data/local/tmp/yapanel_max.tar.gz"
Write-Host "      Передача архива на колонку: $localTar -> $remoteTmp" -ForegroundColor Gray
$pushRes = (& $AdbExe -s $Device push $localTar $remoteTmp 2>&1) | Out-String
if ($tempTarCreated) {
    Remove-Item $localTar -Force -ErrorAction SilentlyContinue
}

Write-Host "      Распаковка в /data/yapanel/..." -ForegroundColor Gray
$unpackCmd = 'su -c "mkdir -p /data/yapanel && tar -xzf /data/local/tmp/yapanel_max.tar.gz -C /data/yapanel/ && chmod -R a+rX /data/yapanel && chmod 755 /data/yapanel/run.sh && chmod 755 /data/yapanel/assistantd 2>/dev/null; rm -f /data/local/tmp/yapanel_max.tar.gz"'
$unpackRes = (& $AdbExe -s $Device shell $unpackCmd 2>&1) | Out-String

# Настройка автозапуска в /data/local/userinit.sh
$autoStartCmd = 'su -c "if [ -f /data/local/userinit.sh ]; then grep -q "/data/yapanel/run.sh" /data/local/userinit.sh || echo "/data/yapanel/run.sh &" >> /data/local/userinit.sh; else echo "#!/system/bin/sh" > /data/local/userinit.sh; echo "/data/yapanel/run.sh &" >> /data/local/userinit.sh; fi; chmod 755 /data/local/userinit.sh"'
& $AdbExe -s $Device shell $autoStartCmd 2>$null | Out-Null

Write-Host "      Файлы панели успешно залиты и права настроены." -ForegroundColor Green

# 6. Перезапуск службы и проверка состояния
Write-Host ""
Write-Host "[6/6] Перезапуск службы и проверка состояния панели..." -ForegroundColor Green
& $AdbExe -s $Device shell 'su -c "pkill -9 -f server.py"' 2>$null | Out-Null
Start-Sleep -Seconds 3

# Запуск run.sh
& $AdbExe -s $Device shell 'su -c "nohup /data/yapanel/run.sh >/dev/null 2>&1 &"' 2>$null | Out-Null

$panelUrl = "http://" + $TargetIP + ":8765"
$dspUrl = $panelUrl + "/api/dsp"
$partyUrl = $panelUrl + "/api/party/status"

Write-Host "      Ожидание запуска веб-сервера на $panelUrl..." -ForegroundColor Gray

$ready = $false
for ($i = 1; $i -le 15; $i++) {
    Start-Sleep -Seconds 2
    try {
        $resp = Invoke-RestMethod -Uri $dspUrl -Method Get -TimeoutSec 4 -ErrorAction SilentlyContinue
        if ($resp.supported -ne $null) {
            $ready = $true
            break
        }
    } catch {}
    Write-Host "      ...проверка связи $i/15" -ForegroundColor Gray
}

if (-not $ready) {
    $logTail = (& $AdbExe -s $Device shell 'su -c "tail -n 25 /data/yapanel/yapanel.log 2>/dev/null"' 2>&1) | Out-String
    Show-ErrorAndExit ("Панель не ответила на запрос за 30 секунд.`nЖурнал ошибки с колонки:`n" + $logTail)
}

# Проверка Party службы
try {
    $partyResp = Invoke-RestMethod -Uri $partyUrl -Method Get -TimeoutSec 4 -ErrorAction SilentlyContinue
    $partyMode = if ($partyResp.active_mode) { $partyResp.active_mode } else { "party" }
} catch {
    $partyMode = "party"
}

Write-Host ""
Write-Host "======================================================================" -ForegroundColor Green
Write-Host "  УСПЕШНО! YapAnel Hi-Fi & Party Mode установлена и активна!" -ForegroundColor Green
Write-Host "======================================================================" -ForegroundColor Green
Write-Host ""
Write-Host "  [+] Аппаратный DSP Silergy SY6045S: " -NoNewline -ForegroundColor Cyan
Write-Host ("АКТИВЕН (Профиль: " + $resp.active_profile + ")") -ForegroundColor Green
Write-Host "  [+] Светомузыка и атмосферные режимы: " -NoNewline -ForegroundColor Cyan
Write-Host ("ГОТОВЫ (" + $partyMode + ")") -ForegroundColor Green
Write-Host "  [+] Веб-интерфейс доступен по адресу: " -NoNewline -ForegroundColor Cyan
Write-Host ($panelUrl + "/") -ForegroundColor Yellow
Write-Host ""
Write-Host "  Открываю панель управления в браузере..." -ForegroundColor Cyan
try {
    Start-Process ($panelUrl + "/")
} catch {}

Write-Host "  Окно закроется автоматически через 3 секунды..." -ForegroundColor Gray
Start-Sleep -Seconds 3
exit 0
